  /// High-contrast partner of each theme that has one. Used when iOS Increase Contrast is on.
  public static let highContrast: [String: String] = ["default": "evergreen-contrast", "evergreen-dark": "evergreen-dark-contrast", "evergreen-inverse": "evergreen-inverse-contrast", "harbor": "harbor-contrast", "harbor-dark": "harbor-dark-contrast"]

  /// The theme to use for a light/dark pair, following the system colour scheme and Increase Contrast.
  public static func theme(light: String = "default", dark: String = "evergreen-dark", colorScheme: ColorScheme, contrast: ColorSchemeContrast) -> Theme {
    let base = colorScheme == .dark ? dark : light
    let name = contrast == .increased ? (highContrast[base] ?? base) : base
    return themes[name] ?? themes["default"]!
  }
}

private struct LarkmoorThemeKey: EnvironmentKey { static let defaultValue: Larkmoor.Theme = Larkmoor.themes["default"]! }
public extension EnvironmentValues {
  var larkmoor: Larkmoor.Theme { get { self[LarkmoorThemeKey.self] } set { self[LarkmoorThemeKey.self] = newValue } }
}

/// Picks the light, dark or high-contrast theme from the environment and passes it down as \.larkmoor.
public struct LarkmoorThemeModifier: ViewModifier {
  let light: String; let dark: String
  @Environment(\.colorScheme) private var colorScheme
  @Environment(\.colorSchemeContrast) private var contrast
  public func body(content: Content) -> some View {
    let theme = Larkmoor.theme(light: light, dark: dark, colorScheme: colorScheme, contrast: contrast)
    return content.environment(\.larkmoor, theme).tint(theme.colors.action)
  }
}

public extension View {
  /// Applies a Larkmoor theme that follows Dark Mode and Increase Contrast, e.g. .larkmoorTheme(light: "harbor", dark: "harbor-dark").
  func larkmoorTheme(light: String = "default", dark: String = "evergreen-dark") -> some View {
    modifier(LarkmoorThemeModifier(light: light, dark: dark))
  }

  /// Applies a Larkmoor text role: font (scales with Dynamic Type), line spacing, tracking and case.
  func larkmoorText(_ style: Larkmoor.TextStyle) -> some View {
    self.font(style.font).lineSpacing(style.lineSpacing).tracking(style.tracking).textCase(style.uppercase ? .uppercase : nil)
  }
}

/// Primary, secondary and danger buttons with a 44pt minimum hit target and a pressed state.
public struct LarkmoorButtonStyle: ButtonStyle {
  public enum Variant { case primary, secondary, danger }
  let variant: Variant
  @Environment(\.larkmoor) private var theme
  @Environment(\.isEnabled) private var isEnabled
  public init(_ variant: Variant = .primary) { self.variant = variant }
  public func makeBody(configuration: Configuration) -> some View {
    let c = theme.colors
    let fill: Color = variant == .primary ? c.action : variant == .danger ? c.danger : .clear
    let ink: Color = variant == .primary ? c.onAction : variant == .danger ? .white : c.text
    return configuration.label
      .font(theme.body.font.weight(.medium))
      .padding(.horizontal, Larkmoor.Space.s5)
      .frame(minHeight: Larkmoor.Size.target)
      .background(Capsule().fill(fill))
      .overlay(Capsule().strokeBorder(variant == .secondary ? c.borderStrong : .clear, lineWidth: 1))
      .foregroundStyle(ink)
      .opacity(isEnabled ? 1 : 0.55)
      .scaleEffect(configuration.isPressed ? 0.97 : 1)
      .animation(Larkmoor.Motion.standard, value: configuration.isPressed)
      .contentShape(Capsule())
  }
}
